PAYLOAD = ''


def digest(path: Path) -> str | None:
    if not path.exists():
        return None
    return hashlib.sha256(path.read_bytes()).hexdigest()


def load_payload() -> dict[str, bytes]:
    packed = zlib.decompress(base64.b64decode(PAYLOAD.encode("ascii")))
    encoded = json.loads(packed.decode("utf-8"))
    return {name: base64.b64decode(content) for name, content in encoded.items()}


def verify_project_root(root: Path) -> None:
    package_path = root / "package.json"
    if not package_path.is_file():
        raise RuntimeError(
            "Place this installer beside package.json and run it from the "
            "NukeFire client repository."
        )
    package = json.loads(package_path.read_text(encoding="utf-8"))
    if package.get("name") != "nukefire-mac-client":
        raise RuntimeError("This does not appear to be the NukeFire Mac client repository.")


def current_state(root: Path) -> dict[str, str | None]:
    return {name: digest(root / name) for name in TARGET_HASHES}


def report_mismatch(current: dict[str, str | None]) -> None:
    print(
        "The installer stopped because the source is not the confirmed "
        "Milestone 1.4c Tab Groups baseline.",
        file=sys.stderr,
    )
    print("No files were changed. Unexpected paths:", file=sys.stderr)
    for name, expected in BASELINE_HASHES.items():
        if current.get(name) != expected:
            actual = current.get(name) or "missing"
            wanted = expected or "absent"
            print(
                f"  {name}\n    expected: {wanted}\n    found:    {actual}",
                file=sys.stderr,
            )


def run_verify(root: Path) -> None:
    print("\nRunning npm run verify...\n")
    completed = subprocess.run(["npm", "run", "verify"], cwd=root)
    if completed.returncode != 0:
        raise RuntimeError("npm run verify failed")


def main() -> int:
    root = Path(__file__).resolve().parent
    try:
        verify_project_root(root)
    except Exception as error:
        print(f"Installation stopped: {error}", file=sys.stderr)
        return 2

    current = current_state(root)

    if current == TARGET_HASHES:
        print(f"{MILESTONE} is already installed.")
        try:
            run_verify(root)
        except Exception as error:
            print(f"Verification failed: {error}", file=sys.stderr)
            return 1
        return 0

    if current != BASELINE_HASHES:
        report_mismatch(current)
        return 2

    payload = load_payload()
    if set(payload) != set(TARGET_HASHES):
        print("Installation stopped: embedded payload is incomplete.", file=sys.stderr)
        return 2

    backup_root = Path(tempfile.mkdtemp(prefix=".milestone-1.5a-backup-", dir=root))
    existing_paths: set[str] = set()

    try:
        for name in payload:
            source = root / name
            if source.exists():
                existing_paths.add(name)
                backup = backup_root / name
                backup.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(source, backup)

        for name, content in payload.items():
            destination = root / name
            destination.parent.mkdir(parents=True, exist_ok=True)
            temporary = destination.with_name(f".{destination.name}.milestone-1.5a.tmp")
            temporary.write_bytes(content)
            if destination.exists():
                os.chmod(temporary, destination.stat().st_mode)
            else:
                os.chmod(temporary, 0o644)
            os.replace(temporary, destination)

        installed = current_state(root)
        if installed != TARGET_HASHES:
            raise RuntimeError(
                "Installed files did not match the verified Milestone 1.5a payload"
            )

        run_verify(root)
    except Exception as error:
        print(f"\nInstallation failed: {error}", file=sys.stderr)
        print("Restoring the confirmed Milestone 1.4c files...", file=sys.stderr)
        for name in payload:
            destination = root / name
            backup = backup_root / name
            if name in existing_paths and backup.exists():
                destination.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(backup, destination)
            elif destination.exists():
                destination.unlink()
        shutil.rmtree(backup_root, ignore_errors=True)
        return 1

    shutil.rmtree(backup_root, ignore_errors=True)
    print(f"\n{MILESTONE} installed successfully.")
    print("Communications is now a dockable panel with filters, search, timestamps, unread counts, and clear controls.")
    print("Recognized communications remain visible in the complete main terminal output.")
    print("The terminal scrolling, pagination, command pipeline, Telnet parser, and GMCP transport were not rewritten.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
